from tools.mcptester.mcptester.scenarios.base import BaseScenario, TestCase

class InvestigationScenario(BaseScenario):
    name = 'investigation'
    description = 'Investigation state tools'

    def get_test_cases(self) -> list[TestCase]:
        return [TestCase(name='get_investigation_state_existing', tool='get_investigation_state', params={'binder_id': 'binder_001'}, expected={'json_valid': True, 'error': False, 'contains_keys': ['id', 'investigation_id', 'current_phase']}, description='Get investigation state for binder_001'), TestCase(name='get_investigation_state_not_found', tool='get_investigation_state', params={'binder_id': 'nonexistent_binder'}, expected={'contains_keys': ['error']}, description='Get state for non-existent binder returns error'), TestCase(name='get_phase_states_basic', tool='get_phase_states', params={'binder_id': 'binder_001'}, expected={'is_array': True, 'error': False, 'array_length_range': [7, 7], 'all_items_keys': ['id', 'artifact_type', 'phase_number']}, description='Get all 7 phase states for binder_001'), TestCase(name='get_phase_states_completed', tool='get_phase_states', params={'binder_id': 'binder_001', 'status': 'completed'}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='Get completed phase states'), TestCase(name='get_phase_states_running', tool='get_phase_states', params={'binder_id': 'binder_001', 'status': 'running'}, expected={'is_array': True, 'error': False}, description='Get running phase states (should be 0 - all completed)'), TestCase(name='list_investigations_default', tool='list_investigations_with_state', params={}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='List investigations with state'), TestCase(name='list_investigations_confident', tool='list_investigations_with_state', params={'outcome': 'CONFIDENT'}, expected={'is_array': True, 'error': False}, description='List CONFIDENT investigations'), TestCase(name='list_investigations_active', tool='list_investigations_with_state', params={'status': 'active'}, expected={'is_array': True, 'error': False}, description='List active investigations'), TestCase(name='list_investigations_limited', tool='list_investigations_with_state', params={'limit': 1}, expected={'is_array': True, 'error': False, 'array_length_range': [0, 1]}, description='List investigations with limit 1'), TestCase(name='find_similar_by_function', tool='find_similar_investigations', params={'error_function': 'BoardReader::processData'}, expected={'is_array': True, 'error': False}, description='Find similar investigations by function name'), TestCase(name='find_similar_by_message', tool='find_similar_investigations', params={'error_message_pattern': 'timeout'}, expected={'is_array': True, 'error': False}, description='Find similar investigations by message pattern'), TestCase(name='find_similar_combined', tool='find_similar_investigations', params={'error_function': 'BoardReader', 'error_message_pattern': 'Timeout', 'limit': 5}, expected={'is_array': True, 'error': False}, description='Find similar with combined filters')]